INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.98.0',
  '2026-09-23',
  'Настройки: картинку фона можно развернуть на весь экран',
  E'В «Оформлении», у каждой картинки фона появилась третья кнопка — «⤢» в левом нижнем углу плитки. Она открывает картинку целиком на весь экран, ничего не меняя: по маленькой плитке 84×84 не понять, что там на самом деле.\n\nВнизу две кнопки: «Закрыть» и «Установить». Если эта картинка уже стоит фоном, вместо второй кнопки написано «Установлен ✓». Закрыть можно и клавишей Esc или щелчком мимо картинки.\n\nРаботает и на своих картинках, и на общей галерее; в галерее «⤢» именно разворачивает, а не ставит фоном — раньше любое касание плитки сразу меняло фон.',
  E'BackgroundPicker.vue: состояние preview = {src, url, id, filename} — src для <img> (полный размер, не миниатюра), url в том виде, в каком его хранит сервер, чтобы сравнением с bg.url понять, стоит ли картинка фоном (previewOn). Свою картинку ставим по id (useImage), галерейную — по имени файла; адрес галереи вынесен в galleryFullUrl(), useGallery теперь зовёт его, иначе сравнение с bg.url пришлось бы дублировать.\n\nОкно живёт в том же Teleport to body, что и остальные модалки (у карточек backdrop-filter — он делает содержащий блок для position: fixed), z-index 1300 над ними. Разметка — колонка: .viewer-pic с flex: 1 и min-height: 0 (без него картинка распирает колонку и кнопки уезжают за экран), картинка max-width/height: 100% + object-fit: contain, полоса кнопок с padding-bottom calc(10px + env(safe-area-inset-bottom)). После «Установить» окно не закрывается — кнопка гаснет и меняется на «Установлен ✓», иначе не видно, что что-то произошло. Esc — общий слушатель keydown, ставится в onMounted и снимается в onUnmounted рядом с botTimer.\n\nКнопки на плитке разведены по углам: .mini.fld слева сверху (правило .mini:not(.del) заменено явным классом), .mini.del справа сверху, .mini.zoom слева снизу. На плитке галереи у «⤢» стоит @click.stop — сам div плитки по клику ставит фон.\n\nПроверено в браузере на локальном сервере: своя картинка и картинка галереи, установка из окна (метка .thumb.on появляется), «Установлен ✓» для текущего фона, Esc, отсутствие наложения трёх кнопок на плитке 93×93.'
);
-- +goose StatementEnd

